  f_committed:=public.web_commit_basic_care_binding_intent(f_t,f_c,f_u,f_issue_req,f_hash);SELECT r.original INTO f_issue_receipt FROM care_private.basic_care_binding_requests r WHERE r.request_id=f_issue_req;
