  BEGIN UPDATE public.care_tour_stops SET notes='Synthetic native drift after commit'WHERE id=f_visit;IF public.web_confirm_basic_care_binding_intent(f_t,f_c,f_u,f_issue_req,f_hash)IS DISTINCT FROM f_committed THEN RAISE EXCEPTION 'Native drift changed historical committed receipt';END IF;RAISE EXCEPTION USING ERRCODE='Z0002';EXCEPTION WHEN SQLSTATE 'Z0002'THEN NULL;END;
  f_cancel_text:=(f_other_issue||jsonb_build_object('requestId',f_cancel_req))::text;f_cancel_hash:=care_private.basic_care_packet_text_hash(f_cancel_text);PERFORM public.web_prepare_basic_care_binding_intent(f_cancel_text,f_cancel_hash);f_cancelled:=public.web_cancel_basic_care_binding_intent(f_t,f_c,f_u,f_cancel_req,f_cancel_hash);
