  BEGIN
   INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data)VALUES(f_relinked,f_relinked||'@example.invalid','{}','{}');DELETE FROM public.profiles WHERE id=f_relinked;UPDATE public.profiles SET auth_user_id=f_relinked WHERE id=f_u;INSERT INTO auth.sessions(id,user_id,not_after)VALUES(f_relinked_s,f_relinked,clock_timestamp()+interval '1 hour');PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f_relinked,'role','authenticated','session_id',f_relinked_s,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint)::text,true);
